 p_id=>wwv_flow_imp.id(111555481062306234844)
,p_plugin_type=>'REGION TYPE'
,p_name=>'GRAPHVIZ'
,p_display_name=>'Graph Visualization (Preview)'
,p_image_prefix => nvl(wwv_flow_application_install.get_static_plugin_file_prefix('REGION TYPE','GRAPHVIZ'),'')
,p_javascript_file_urls=>wwv_flow_string.join(wwv_flow_t_varchar2(
'#PLUGIN_FILES#index.js',
'[require requirejs]#PLUGIN_FILES#wrapper.js'))
,p_css_file_urls=>wwv_flow_string.join(wwv_flow_t_varchar2(
'#PLUGIN_FILES#alta.css',
'#PLUGIN_FILES#wrapper.css',
'#PLUGIN_FILES#bundle.css'))
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function render(',
'    p_region              in apex_plugin.t_region,',
'    p_plugin              in apex_plugin.t_plugin,',
'    p_is_printer_friendly in boolean)',
'    return apex_plugin.t_region_render_result',
'is',
'    c_id constant varchar2(255) := apex_escape.html_attribute(p_region.static_id) || ''-container'';',
'    ',
'    c_template_settings constant p_region.attribute_02%type := p_plugin.attribute_01;',
'    c_template_styles   constant p_region.attribute_03%type := p_plugin.attribute_02;',
'    ',
'    c_settings          constant p_region.attribute_02%type := p_region.attribute_02;',
'    c_styles            constant p_region.attribute_03%type := p_region.attribute_03;',
'    c_layout            constant p_region.attribute_04%type := p_region.attribute_04;',
'    c_group_edges       constant p_region.attribute_05%type := p_region.attribute_05;',
'    c_page_size         constant p_region.attribute_06%type := p_region.attribute_06;',
'    c_vertex_label      constant p_region.attribute_07%type := p_region.attribute_07;',
'    c_edge_label        constant p_region.attribute_08%type := p_region.attribute_08;',
'    c_max_label_length  constant p_region.attribute_09%type := p_region.attribute_09;',
'    c_display           constant p_region.attribute_10%type := p_region.attribute_10;',
'    c_expand            constant p_region.attribute_11%type := p_region.attribute_11;',
'    c_fetch_actions     constant p_region.attribute_12%type := p_region.attribute_12;',
'    c_persist           constant p_region.attribute_13%type := p_region.attribute_13;',
'    c_update_graph_data constant p_region.attribute_15%type := p_region.attribute_15;',
'    c_height            constant p_region.attribute_16%type := p_region.attribute_16;',
'begin',
'    apex_plugin_util.debug_region(',
'        p_plugin => p_plugin,',
'        p_region => p_region );',
'        ',
'    sys.htp.prn(''<div id="'' || c_id || ''"></div>'');',
'',
'    apex_javascript.add_onload_code(''initializeGVT(''',
'     || apex_javascript.add_value(p_region.static_id)',
'     || apex_javascript.add_value(c_id)',
'     || apex_javascript.add_value(apex_plugin.get_ajax_identifier)',
'     || apex_javascript.add_value(p_region.attribute_14 = ''Y'')',
'     || apex_javascript.add_value(c_template_settings)',
'     || apex_javascript.add_value(c_template_styles)',
'     || apex_javascript.add_value(c_settings)',
'     || apex_javascript.add_value(c_styles)',
'     || apex_javascript.add_value(c_layout)',
'     || apex_javascript.add_value(c_group_edges)',
'     || apex_javascript.add_value(c_page_size)',
'     || apex_javascript.add_value(c_vertex_label)',
'     || apex_javascript.add_value(c_edge_label)',
'     || apex_javascript.add_value(c_max_label_length)',
'     || apex_javascript.add_value(c_display)',
'     || apex_javascript.add_value(c_expand)',
'     || apex_javascript.add_value(c_fetch_actions)',
'     || apex_javascript.add_value( p_value => c_persist )',
'     || apex_javascript.add_value(c_height )',
'     || apex_javascript.add_value( c_update_graph_data, p_add_comma => false )',
'     || '');'' );',
'   ',
'    return null;',
'end render;',
'',
'',
'$IF DBMS_DB_VERSION.VERSION >= 23 $THEN',
'',
'FUNCTION APEX_SQLGRAPH_TO_JSON( ',
'  APEX_CURSOR APEX_EXEC.T_CONTEXT, ',
'  PAGE_START NUMBER DEFAULT NULL, ',
'  PAGE_SIZE NUMBER DEFAULT NULL',
') RETURN CLOB ',
'IS ',
'  M_VCSIZ_4K                              CONSTANT PLS_INTEGER := 4000; ',
'  M_VCSIZ_32K                             CONSTANT PLS_INTEGER := 32672; ',
'  JSON_FILE                               CLOB; --the returned result ',
'  GRAPHNAME                               VARCHAR2(M_VCSIZ_4K); ',
'  ELEMENT_NAME                            VARCHAR2(M_VCSIZ_4K); ',
'  GRAPHOWNER                              VARCHAR2(M_VCSIZ_4K); ',
'  L_COLS                                  INTEGER; ',
'  L_FLAG                                  NUMBER; ',
'  L_JSON                                  VARCHAR2(M_VCSIZ_4K); ',
'  VERTEX_ID_COLUMN_LIST                   SYS.ODCINUMBERLIST := SYS.ODCINUMBERLIST(); ',
'  EDGE_ID_COLUMN_LIST                     SYS.ODCINUMBERLIST := SYS.ODCINUMBERLIST(); ',
'  P1                                      NUMBER := 1; ',
'  V1                                      NUMBER := 1; ',
'  E1                                      NUMBER := 1; ',
'  VERTEX_TABLE                            SYS.ODCIRIDLIST := SYS.ODCIRIDLIST(); ',
'  EDGE_TABLE                              SYS.ODCIRIDLIST := SYS.ODCIRIDLIST(); ',
'  V2                                      NUMBER := 1; ',
'  E2                                      NUMBER := 1; ',
'  L_HAVING_ELEMENT_ID                     BOOLEAN := FALSE; ',
'  COUNTER                                 NUMBER := 0; ',
'  QUERY_STRING                            VARCHAR2(M_VCSIZ_4K);',
'  FUNCTION_COUNT                          NUMBER;',
'  VERTEX_GROUP                            SYS.ODCINUMBERLIST := SYS.ODCINUMBERLIST();',
'  EDGE_GROUP                              SYS.ODCINUMBERLIST := SYS.ODCINUMBERLIST();',
'BEGIN ',
'',
'    select COUNT(*) INTO FUNCTION_COUNT from ALL_PROCEDURES WHERE OBJECT_NAME = ''DBMS_GVT'' AND PROCEDURE_NAME = ''BUILD_JSON'';',
'',
'    IF FUNCTION_COUNT < 1 THEN',
'        RAISE_APPLICATION_ERROR(-20000, ''Please install DBMS_GVT package.'');',
'    END IF;',
'',
'    L_COLS := APEX_EXEC.GET_COLUMN_COUNT(APEX_CURSOR); ',
'',
'    WHILE APEX_EXEC.NEXT_ROW( ',
'        P_CONTEXT => APEX_CURSOR ',
'    ) LOOP ',
'        COUNTER := COUNTER + 1; ',
'        IF ((PAGE_START < 0 ',
'        OR PAGE_SIZE <= 0) ',
'        AND (PAGE_START IS NOT NULL',
'        AND PAGE_SIZE IS NOT NULL)) THEN ',
'            RAISE_APPLICATION_ERROR(-20000, ''Please provide valid values for page_start and page_size parameter. page_start should be an integer equal to or greater than 0. page_size should be an integer greater than 0''); ',
'        END IF; ',
' ',
'        IF ((COUNTER > PAGE_START ',
'        AND COUNTER <= PAGE_START + PAGE_SIZE) ',
'        OR (PAGE_START IS NULL ',
'        AND PAGE_START IS NULL) ) THEN ',
'            IF P1 = 1 THEN ',
'                FOR POS IN 1 .. L_COLS LOOP ',
'                    IF APEX_EXEC.GET_COLUMN(APEX_CURSOR, POS).DATA_TYPE = 11 THEN ',
'                        L_JSON := APEX_EXEC.GET_CLOB(APEX_CURSOR, POS); ',
'                        IF JSON_EXISTS(L_JSON, ''$.ELEM_TABLE'') AND JSON_EXISTS(L_JSON, ''$.GRAPH_OWNER'') AND JSON_EXISTS(L_JSON, ''$.GRAPH_NAME'') AND JSON_EXISTS(L_JSON, ''$.KEY_VALUE'') THEN ',
'                            L_HAVING_ELEMENT_ID := TRUE; ',
'                            IF GRAPHNAME IS NULL AND GRAPHOWNER IS NULL THEN ',
'                                GRAPHNAME := JSON_VALUE(L_JSON, ''$.GRAPH_NAME''); ',
'                                GRAPHOWNER := JSON_VALUE(L_JSON, ''$.GRAPH_OWNER''); ',
'                            END IF; ',
' ',
'                            SELECT ',
'                                ELEMENT_KIND INTO ELEMENT_NAME ',
'                            FROM ',
'                                ALL_PG_ELEMENTS ',
'                            WHERE ',
'                                ELEMENT_NAME = JSON_VALUE(L_JSON, ''$.ELEM_TABLE'') ',
'                                AND GRAPH_NAME = GRAPHNAME ',
'                                AND OWNER = GRAPHOWNER; ',
'                            IF ELEMENT_NAME = ''VERTEX'' THEN ',
'                                VERTEX_ID_COLUMN_LIST.EXTEND; ',
'                                VERTEX_ID_COLUMN_LIST(V1) := POS; ',
'                                V1 := V1 + 1; ',
'                                VERTEX_TABLE.EXTEND(); ',
'                                VERTEX_TABLE(V2) := L_JSON; ',
'                                VERTEX_GROUP.EXTEND();',
'                                VERTEX_GROUP(V2) := POS;',
'                                V2 := V2 + 1; ',
'                            ELSE ',
'                                EDGE_ID_COLUMN_LIST.EXTEND; ',
'                                EDGE_ID_COLUMN_LIST(E1) := POS; ',
'                                E1 := E1 + 1; ',
'                                EDGE_TABLE.EXTEND(); ',
'                                EDGE_TABLE(E2) := L_JSON; ',
'                                EDGE_GROUP.EXTEND();',
'                                EDGE_GROUP(E2) := POS;',
'                                E2 := E2 + 1; ',
'                            END IF; ',
'                        END IF; ',
'                    END IF; ',
'                END LOOP; ',
'            ELSE ',
'                FOR I IN 1..VERTEX_ID_COLUMN_LIST.COUNT LOOP ',
'                    L_JSON := APEX_EXEC.GET_CLOB(APEX_CURSOR, VERTEX_ID_COLUMN_LIST(I)); ',
'                    VERTEX_TABLE.EXTEND(); ',
'                    VERTEX_TABLE(V2) := L_JSON; ',
'                    VERTEX_GROUP.EXTEND(); ',
'                    VERTEX_GROUP(V2) := VERTEX_ID_COLUMN_LIST(I);',
'                    V2 := V2 + 1; ',
'                END LOOP; ',
' ',
'                FOR I IN 1..EDGE_ID_COLUMN_LIST.COUNT LOOP ',
'                    L_JSON := APEX_EXEC.GET_CLOB(APEX_CURSOR, EDGE_ID_COLUMN_LIST(I)); ',
'                    EDGE_TABLE.EXTEND(); ',
'                    EDGE_TABLE(E2) := L_JSON; ',
'                    EDGE_GROUP.EXTEND();',
'                    EDGE_GROUP(E2) := EDGE_ID_COLUMN_LIST(I);',
'                    E2 := E2 + 1; ',
'                END LOOP; ',
'            END IF; ',
' ',
'            P1 := P1 + 1; ',
'        END IF; ',
'    END LOOP; ',
' ',
'    IF NOT L_HAVING_ELEMENT_ID  AND COUNTER != 0 THEN ',
'        RAISE_APPLICATION_ERROR(-20000, ''Please add vertex_id/edge_id in CLOUMNS clause''); ',
'    END IF; ',
'    QUERY_STRING := ''SELECT DBMS_GVT.BUILD_JSON(:1, :2, :3, :4, :5, :6, :7) FROM DUAL'';',
'',
'    EXECUTE IMMEDIATE QUERY_STRING INTO JSON_FILE USING VERTEX_TABLE, EDGE_TABLE, COUNTER, GRAPHNAME, GRAPHOWNER, VERTEX_GROUP, EDGE_GROUP;',
'',
'    RETURN JSON_FILE; ',
'END APEX_SQLGRAPH_TO_JSON;',
'',
'$END',
'',
'function ajax(',
'    p_region in apex_plugin.t_region,',
'    p_plugin in apex_plugin.t_plugin',
') return apex_plugin.t_region_ajax_result',
'is',
'    l_parameters apex_exec.t_parameters;',
'    l_context apex_exec.t_context;',
'    temp clob;',
'    page_start NUMBER;',
'    page_size NUMBER;',
'begin   ',
'    $IF DBMS_DB_VERSION.VERSION >= 23 $THEN',
'        if p_region.attribute_14 = ''Y'' then',
'           page_start := apex_application.g_x01;',
'           page_size := apex_application.g_x02;',
'        end if;',
'        ',
'        l_context := apex_exec.open_query_context(p_sql_parameters => l_parameters, p_first_row => 1); ',
'        temp := apex_sqlgraph_to_json(l_context, page_start, page_size);',
'        apex_util.prn(temp, false);',
'    $ELSE',
'        if p_region.attribute_14 = ''Y'' then',
'           apex_exec.add_parameter(l_parameters, ''page_start'', apex_application.g_x01);',
'           apex_exec.add_parameter(l_parameters, ''page_size'', apex_application.g_x02);',
'        end if;',
'            ',
'        l_context := apex_exec.open_query_context(p_sql_parameters => l_parameters, p_first_row => 1, p_max_rows => 1);',
'',
'        if apex_exec.next_row(p_context => l_context) then',
'           apex_util.prn(apex_exec.get_clob(l_context, 1), false);',
'        end if;',
'    $END',
'    apex_exec.close(l_context);',
'    return null;',
'exception ',
'    when others then',
'        apex_exec.close(l_context);',
'        raise;        ',
'end ajax;'))
,p_default_escape_mode=>'HTML'
,p_api_version=>2
,p_render_function=>'render'
,p_ajax_function=>'ajax'
,p_standard_attributes=>'SOURCE_LOCATION:AJAX_ITEMS_TO_SUBMIT:COLUMNS:VALUE_ESCAPE_OUTPUT'
,p_substitute_attributes=>true
,p_subscribe_plugin_settings=>true
,p_version_identifier=>'23.2.0'
,p_files_version=>1448
);
