wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(15284892928330152)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Expand'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE data clob;',
'id VARCHAR2(100) := apex_exec.enquote_literal(apex_application.g_x01);',
'graph VARCHAR2(100) := ''EBA_SAMPLE_GRAPH'';',
'hops NUMBER := 2;',
'n NUMBER := hops - 1;',
'query VARCHAR2(1000) := ''SELECT id_x, id_e, id_z',
'FROM GRAPH_TABLE ('' || graph || '' MATCH (x) ->{,'' || n || ''} (y) -[e]-> (z) WHERE JSON_value(vertex_id(x), ''''$.ELEM_TABLE'''') || json_query(vertex_id(x), ''''$.KEY_VALUE'''' returning varchar2) = ''|| id ||''',
'COLUMNS (vertex_id(x) as id_x, edge_id(e) as id_e, vertex_id(z) as id_z))'';',
'',
'BEGIN',
'SELECT CUST_SQLGRAPH_JSON(query) INTO data FROM sys.dual;',
'htp.p(data);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>6724956336055901
);
end;
