,p_plug_display_sequence=>30
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'The state saving is done by making use of the scripts passed via the two attributes <b>FetchActions</b> ',
'and <b>Persist</b> (Settings > Fetch Actions, Persist in APEX). The data during save is persisted in the GRAPH_ACTION database table.',
'<br><br><strong>Fetch Actions:</strong><br>',
'<code>',
' const actions = await apex.server.process(''Fetch'',null, {dataType: ''text''});',
'    try {',
'        return JSON.parse(actions)',
'    } catch (error) {',
'        return [];',
'    }',
'',
'</code>',
'<br><strong>Persist:</strong><br>',
'<code>',
'    await apex.server.process(''Persist'', {',
'        x01: JSON.stringify(action)',
'    }, {dataType: ''text''});',
'',
'</code>',
'<br><strong>Query:</strong><br>',
'<code>',
'/*  In the below query, data is selected from Property and made into',
'    JSON format that GVT accepts.',
'',
'    The query retrieves vertices and edges of the graph that visualizes ',
'    the reporting structure of employees to their managers.*/',
'',
'SELECT employee,e, manager',
'FROM GRAPH_TABLE ( EBA_SAMPLE_GRAPH',
'  MATCH (m IS EMPLOYEE ) -[e IS WORKS_FOR ]-> (n)',
'  COLUMNS (vertex_id(m) AS employee, edge_id(e) AS e, vertex_id(n) AS manager )',
')',
'</code>'))
,p_attribute_01=>'N'
,p_attribute_02=>'HTML'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(20479048573136660)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Persist'
,p_process_sql_clob=>'INSERT INTO EBA_GRAPHVIZ_GRAPH_ACTION(ACTION, USER_ID) VALUES(apex_application.g_x01, v(''APP_USER''));'
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'error occured during persist'
,p_internal_uid=>11919111980862409
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(20479469051136662)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Fetch'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    data clob;',
'BEGIN',
'    SELECT JSON_ARRAYAGG(action FORMAT JSON ORDER BY ID ASC returning clob) INTO data FROM EBA_GRAPHVIZ_GRAPH_ACTION WHERE USER_ID = v(''APP_USER'');',
'    htp.p(data);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>11919532458862411
);
end;
