wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(30389730678395278882)
,p_plug_name=>'Details'
,p_region_template_options=>'#DEFAULT#:is-expanded:i-h640:t-Region--scrollBody'
